      "category": "sequence_interest",
      "rationale": "Across all four datasets, blend each normalized encoder state with the causal mean of up to four recent nonpadding states: 0.8 current + 0.2 recent mean. This may stabilize short histories while retaining the latest state's dominance. Preserve the causal backbone, embeddings, scoring, loss and optimizer. The predictor imports the updated model class; a metadata check keeps its readout consistent with training.",
      "edits": [
        {
          "find": "        return self.norm(x)\n\n    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):",
          "replace": "        states = self.norm(x)\n        valid = observed.unsqueeze(-1).to(dtype=states.dtype)\n        masked_states = states * valid\n        state_prefix = nn.functional.pad(masked_states.cumsum(dim=1), (0, 0, 1, 0))\n        count_prefix = nn.functional.pad(valid.cumsum(dim=1), (0, 0, 1, 0))\n        starts = (torch.arange(length, device=seq.device) - 3).clamp(min=0)\n        recent_sum = state_prefix[:, 1:] - state_prefix.index_select(1, starts)\n        recent_count = count_prefix[:, 1:] - count_prefix.index_select(1, starts)\n        recent_mean = recent_sum / recent_count.clamp(min=1.0)\n        return (0.8 * states + 0.2 * recent_mean) * valid\n\n    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):"
        },
